static inline pcap_rmtauth* build_safe_rmtauth(
    bool is_null,
    const std::vector<uint8_t>& blob,
    pcap_rmtauth& auth,
    std::vector<uint8_t>& user_storage,
    std::vector<uint8_t>& pass_storage) {
    if (is_null) return nullptr;
    std::memset(&auth, 0, sizeof(auth));
    auth.type = 0;
    if (blob.empty()) return &auth;

    const size_t ulen = std::min<size_t>(std::max<size_t>(blob.size() / 2, 1), 31);
    const size_t plen = std::min<size_t>(std::max<size_t>(blob.size() - (blob.size() / 2), 1), 31);
    user_storage.resize(ulen + 1);
    pass_storage.resize(plen + 1);
    for (size_t i = 0; i < ulen; i++) {
        user_storage[i] = (uint8_t)('a' + (blob[i % blob.size()] % 26));
    }
    for (size_t i = 0; i < plen; i++) {
        pass_storage[i] = (uint8_t)('a' + (blob[(blob.size() - 1 - (i % blob.size()))] % 26));
    }
    user_storage[ulen] = 0;
    pass_storage[plen] = 0;
    auth.type = 1;
    auth.username = reinterpret_cast<char*>(user_storage.data());
    auth.password = reinterpret_cast<char*>(pass_storage.data());
    return &auth;
}

